'use strict';
const AudioLab=(()=>{
let track=null,worker=null,busy=false,url=null,alpha=null,loopTimer=null;
const xml=s=>String(s??'').replace(/[<>&"']/g,c=>({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&apos;'}[c]));
const dbPromise=new Promise((resolve,reject)=>{const request=indexedDB.open('palco-audio',1);request.onupgradeneeded=()=>request.result.createObjectStore('tracks',{keyPath:'id'});request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});
async function dbOp(action,value){const db=await dbPromise;return new Promise((resolve,reject)=>{const tx=db.transaction('tracks',action==='getAll'?'readonly':'readwrite'),req=tx.objectStore('tracks')[action](value);let result;req.onsuccess=()=>result=req.result;tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error);});}
function time(n){return Math.floor(n/60)+':'+Math.floor(n%60).toString().padStart(2,'0');}
function guitar(midi){const opens=[64,59,55,50,45,40];let best=null;for(let s=0;s<6;s++){const fret=midi-opens[s];if(fret>=0&&fret<=24&&(!best||fret<best.fret))best={string:s+1,fret};}return best;}
function monoNotes(notes){const sorted=notes.filter(n=>n.midi>=40&&n.midi<=88).sort((a,b)=>a.start-b.start||b.confidence-a.confidence),out=[];for(const n of sorted){const last=out[out.length-1];if(last&&n.start<last.start+Math.min(last.duration,.12))continue;out.push(n);}return out;}
function exportXML(t){const bpm=t.bpm||90,division=4,beat=60/bpm,ns=monoNotes(t.notes||[]),measureTicks=16;let bars=[],bar=[],position=0;
function pushNote(item,ticks){while(ticks>0){const len=Math.min(ticks,measureTicks-position);bar.push(item(len));position+=len;ticks-=len;if(position===measureTicks){bars.push(bar.join(''));bar=[];position=0;}}}
const rest=len=>`<note><rest/><duration>${len}</duration></note>`;
let previousEnd=0;const lyricSegments=new Set();for(const n of ns){const start=Math.max(previousEnd,Math.round(n.start/beat*division));if(start>previousEnd)pushNote(rest,start-previousEnd);const len=Math.max(1,Math.round(n.duration/beat*division));const end=ns.find(x=>x.start>n.start)?.start;const segment=Math.floor(n.start/15),lyric=t.manualLyrics?.[segment]??(t.lyrics||[]).filter(c=>c.timestamp&&c.timestamp[0]<(segment+1)*15&&(c.timestamp[1]??t.duration)>segment*15).map(c=>c.text.trim()).join(" "),lyricTag=lyric&&!lyricSegments.has(segment)?`<lyric><text>${xml(lyric)}</text></lyric>`:"";lyricSegments.add(segment);const ticks=Math.min(len,end?Math.max(1,Math.round((end-n.start)/beat*division)):len);const names=['C','C','D','D','E','F','F','G','G','A','A','B'],pc=n.midi%12,alter=[1,3,6,8,10].includes(pc)?'<alter>1</alter>':'',g=guitar(n.midi);
pushNote(l=>`<note><pitch><step>${names[pc]}</step>${alter}<octave>${Math.floor(n.midi/12)-1}</octave></pitch><duration>${l}</duration>${g?`<notations><technical><string>${g.string}</string><fret>${g.fret}</fret></technical></notations>`:''}${lyricTag}</note>`,ticks);previousEnd=start+ticks;}
if(position){bar.push(rest(measureTicks-position));bars.push(bar.join(''));}return `<?xml version="1.0" encoding="UTF-8"?><score-partwise version="4.0"><work><work-title>${xml(t.name)} — rascunho automático</work-title></work><part-list><score-part id="P1"><part-name>Melodia estimada</part-name></score-part></part-list><part id="P1">${bars.map((b,i)=>`<measure number="${i+1}">${i===0?`<attributes><divisions>4</divisions><key><fifths>0</fifths></key><time><beats>4</beats><beat-type>4</beat-type></time><clef><sign>G</sign><line>2</line></clef><staff-details><staff-lines>6</staff-lines><staff-tuning line="1"><tuning-step>E</tuning-step><tuning-octave>2</tuning-octave></staff-tuning><staff-tuning line="2"><tuning-step>A</tuning-step><tuning-octave>2</tuning-octave></staff-tuning><staff-tuning line="3"><tuning-step>D</tuning-step><tuning-octave>3</tuning-octave></staff-tuning><staff-tuning line="4"><tuning-step>G</tuning-step><tuning-octave>3</tuning-octave></staff-tuning><staff-tuning line="5"><tuning-step>B</tuning-step><tuning-octave>3</tuning-octave></staff-tuning><staff-tuning line="6"><tuning-step>E</tuning-step><tuning-octave>4</tuning-octave></staff-tuning></staff-details></attributes><direction><sound tempo="${bpm}"/></direction>`:''}${b}</measure>`).join('')}</part></score-partwise>`;}
function download(name,content,type){const u=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function status(text,error=false){const el=$('#labstatus');if(el){el.textContent=text;el.classList.toggle('error',error);}}
function page(){return head('TOCAR & CRIAR','Do áudio para o estudo.','Importe sua música, ouça trechos e gere um rascunho musical para revisar.')+`<div class="hint" style="margin:0 0 20px"><b class="green">TRANSCRIÇÃO EXPERIMENTAL</b><br>As notas são estimadas automaticamente, com melhores resultados para um instrumento isolado. Tab e partitura representam uma melodia selecionada, não todos os instrumentos. A letra usa reconhecimento de voz e também precisa de revisão.</div><div class="uploadarea"><label>Escolher áudio MP3, WAV ou M4A (até 25 MB / 8 minutos)<input id="audiofile" type="file" accept="audio/mpeg,audio/wav,audio/mp4,audio/x-m4a,.mp3,.wav,.m4a"></label><label>Ou abrir uma tablatura Guitar Pro / MusicXML<input id="tabfile" type="file" accept=".gp,.gp3,.gp4,.gp5,.gpx,.xml,.musicxml,.mxl"></label><p class="subtext">O áudio e os resultados ficam neste navegador. Os modelos são baixados no primeiro uso; seu áudio é processado no aparelho.</p></div><div id="labstatus" role="status" class="hint">Escolha um arquivo para começar.</div><div id="savedtracks"></div><div id="trackpanel"></div><section id="importedscore" class="panel hide"><h2>Tablatura importada</h2><div id="tabrender"></div></section>`;}
async function mount(){try{const tracks=await dbOp('getAll');$('#savedtracks').innerHTML=tracks.length?`<label>Músicas importadas<select id="savedtrack"><option value="">Selecione uma música</option>${tracks.map(t=>`<option value="${esc(t.id)}">${esc(t.name)}</option>`).join('')}</select></label>`:'';if(track)display();}catch{status('Armazenamento de áudio indisponível neste navegador.',true);}}
async function importAudio(file){if(!file)return;if(busy)return status('Aguarde o processamento em andamento.');if(file.size>25*1024*1024)return status('Arquivo muito grande. Limite: 25 MB.',true);if(!/\.(mp3|wav|m4a)$/i.test(file.name))return status('Use MP3, WAV ou M4A.',true);try{status('Abrindo áudio…');const context=new AudioContext(),buffer=await context.decodeAudioData(await file.arrayBuffer());await context.close();if(buffer.duration>480)return status('O limite desta versão é 8 minutos.',true);track={id:crypto.randomUUID(),name:file.name,blob:file,duration:buffer.duration,bpm:90,notes:[],lyrics:[],manualLyrics:{}};await dbOp('put',track);await mount();display();status('Áudio importado. Escolha o processamento abaixo.');}catch(e){status('Não foi possível abrir ou salvar este áudio: '+e.message,true);}}
function display(){if(!$('#trackpanel')||!track)return;if(url)URL.revokeObjectURL(url);url=URL.createObjectURL(track.blob);$('#trackpanel').innerHTML=`<section class="panel"><div class="sectionhead"><h2>${esc(track.name)}</h2><span class="pill">${time(track.duration)}</span></div><audio id="trackaudio" controls preload="metadata" src="${url}" style="width:100%;margin:15px 0"></audio><div class="settings"><label>BPM para a partitura (ajuste manual)<input id="trackbpm" type="number" min="30" max="240" value="${track.bpm}"></label><label>Velocidade de estudo<select id="audiospeed"><option value="1">100%</option><option value="0.75">75%</option><option value="0.5">50%</option></select></label></div><div class="labactions"><button class="primary" data-lab="notes" ${busy?'disabled':''}>Gerar tab + partitura</button><button class="secondary" data-lab="lyrics" ${busy?'disabled':''}>Reconhecer letra (PT-BR)</button>${track.notes.length?'<button class="secondary" data-lab="export">Exportar MusicXML</button><button class="secondary" data-lab="txt">Exportar tab + letra</button>':''}</div><div class="hint">Modelo musical: Basic Pitch (Spotify). Letra: Whisper tiny. A primeira execução baixa o modelo de voz. Erros, notas fora da guitarra e trechos não reconhecidos são mantidos visíveis para revisão.</div></section><div id="segments" style="margin-top:20px">${segments()}</div>${track.notes.length?'<section class="panel" style="margin-top:20px"><h2>Partitura e tablatura • rascunho quantizado</h2><p class="subtext">4/4, BPM informado. Revise ritmo, oitavas e digitação.</p><div id="autorender"></div></section>':''}`;if(track.notes.length)renderScore(exportXML(track),'#autorender');}
function segmentTab(notes){const selected=monoNotes(notes);if(!selected.length)return 'Nenhuma nota de guitarra identificada neste trecho.';const lines=['e','B','G','D','A','E'].map(s=>s+'|');for(const n of selected){const g=guitar(n.midi);for(let i=0;i<6;i++)lines[i]+=(g&&g.string===i+1?String(g.fret).padStart(2,'-'):'--')+'-';}return lines.map(l=>l+'|').join('\n');}
function segmentLyrics(i){const start=i*15,end=Math.min(track.duration,start+15);return track.manualLyrics?.[i]??track.lyrics.filter(c=>c.timestamp&&c.timestamp[0]<end&&(c.timestamp[1]??end)>start).map(c=>c.text.trim()).join(' ');}
function segments(){return Array.from({length:Math.ceil(track.duration/15)},(_,i)=>{const start=i*15,end=Math.min(track.duration,start+15),ns=track.notes.filter(n=>n.start>=start&&n.start<end);return `<article class="panel segment"><div class="sectionhead"><h2>Trecho ${i+1} <span class="muted">${time(start)} – ${time(end)}</span></h2><button class="secondary" data-segment="${i}">▶ Ouvir trecho</button></div><pre class="tabtext">${esc(track.notes.length?segmentTab(ns):'Gere as notas para ver a tablatura deste trecho.')}</pre><label>Letra do trecho • editável<textarea data-lyric="${i}" rows="2" placeholder="Reconheça a letra ou escreva este trecho manualmente…">${esc(segmentLyrics(i))}</textarea></label><small>${ns.length} notas detectadas • divisão fixa de 15 segundos, não identificação de verso ou refrão</small></article>`;}).join('');}
async function renderScore(source,target,isBytes=false){try{if(!window.alphaTab){await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='alphatab/alphaTab.js';script.onload=resolve;script.onerror=reject;document.head.appendChild(script);});}alpha?.destroy();alpha=new alphaTab.AlphaTabApi($(target),{core:{fontDirectory:'alphatab/font/'},display:{staveProfile:'ScoreTab'},player:{enablePlayer:false}});alpha.error.on(e=>status('O leitor não conseguiu interpretar o arquivo: '+e.message,true));alpha.load(isBytes?source:new TextEncoder().encode(source));}catch(e){status('Não foi possível exibir a partitura: '+(e.message||'falha ao carregar o leitor'),true);}}
async function run(task){if(!track||busy)return;busy=true;display();try{status(task==='notes'?'Preparando áudio para detectar notas…':'Preparando áudio para reconhecer a letra…');const rate=task==='notes'?22050:16000,ac=new AudioContext(),b=await ac.decodeAudioData(await track.blob.arrayBuffer());await ac.close();const offline=new OfflineAudioContext(1,Math.ceil(b.duration*rate),rate),src=offline.createBufferSource();src.buffer=b;src.connect(offline.destination);src.start();const resampled=await offline.startRendering(),samples=resampled.getChannelData(0);worker??=new Worker('audio-worker.js',{type:'module'});await new Promise((resolve,reject)=>{worker.onmessage=async({data:d})=>{if(d.type==='progress'){status(d.text+' • '+d.value+'%');}if(d.type==='error')reject(new Error(d.message));if(d.type==='result'){if(d.task==='notes')track.notes=d.notes;else track.lyrics=d.chunks.length?d.chunks:[{text:d.text,timestamp:[0,track.duration]}];try{await dbOp('put',track);resolve();}catch(e){reject(e);}}};worker.onerror=e=>reject(new Error(e.message||'Erro ao carregar o motor de transcrição.'));worker.postMessage({type:task,samples},[samples.buffer]);});status(task==='notes'?(track.notes.length?track.notes.length+' notas estimadas. Revise o rascunho abaixo.':'Nenhuma nota identificada. Experimente um instrumento isolado.'):'Letra reconhecida. Revise os trechos; canto e acompanhamento podem provocar erros.');}catch(e){status('Processamento não concluído: '+e.message+'. Seu áudio continua salvo; você pode adicionar a letra manualmente.',true);worker?.terminate();worker=null;}finally{busy=false;display();}}
document.addEventListener('change',async e=>{if(e.target.id==='audiofile')importAudio(e.target.files[0]);if(e.target.id==='savedtrack'){if(busy){status('Aguarde o processamento antes de trocar de música.');return;}const tracks=await dbOp('getAll');track=tracks.find(t=>t.id===e.target.value)??null;display();}if(e.target.id==='audiospeed')$('#trackaudio').playbackRate=Number(e.target.value);if(e.target.id==='trackbpm'){track.bpm=Math.max(30,Math.min(240,Number(e.target.value)||90));await dbOp('put',track);display();}if(e.target.dataset.lyric!==undefined){track.manualLyrics??={};track.manualLyrics[e.target.dataset.lyric]=e.target.value;await dbOp('put',track);}if(e.target.id==='tabfile'){const f=e.target.files[0];if(!f)return;if(f.size>10*1024*1024)return status('Limite para tablaturas: 10 MB.',true);$('#importedscore').classList.remove('hide');await renderScore(new Uint8Array(await f.arrayBuffer()),'#tabrender',true);status('Arquivo enviado ao leitor. Verifique a partitura abaixo.');}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.lab==='notes'||b.dataset.lab==='lyrics')run(b.dataset.lab);if(b.dataset.lab==='export')download('ensaio-partitura.musicxml',exportXML(track),'application/vnd.recordare.musicxml+xml');if(b.dataset.lab==='txt')download('ensaio-tab-letra.txt',track.name+'\nRascunho automático para revisão\n\n'+Array.from({length:Math.ceil(track.duration/15)},(_,i)=>`Trecho ${i+1} (${time(i*15)})\n${segmentTab(track.notes.filter(n=>n.start>=i*15&&n.start<(i+1)*15))}\n${segmentLyrics(i)}`).join('\n\n'),'text/plain');if(b.dataset.segment!==undefined){const a=$('#trackaudio'),start=Number(b.dataset.segment)*15,end=Math.min(track.duration,start+15);a.currentTime=start;a.play().catch(()=>status('Clique no player para permitir a reprodução.',true));clearInterval(loopTimer);loopTimer=setInterval(()=>{if(a.currentTime>=end){a.pause();clearInterval(loopTimer);}},100);}});
return{page,mount,guitar,monoNotes,exportXML,stop(){const a=$('#trackaudio');a?.pause();clearInterval(loopTimer);}};
})();
